import type { Config } from "./config";
import { HttpError } from "./http";

export type ChatRole = "user" | "assistant";

export interface ChatMessage {
  role: ChatRole;
  content: string;
}

export interface ChatRequest {
  messages: ChatMessage[];
  shareMedications: boolean;
  medicationContext: string | undefined;
}

/** Install ids are opaque random strings generated by the app on first run. */
const INSTALL_ID_PATTERN = /^[A-Za-z0-9._-]{8,128}$/;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function requireInstallId(request: Request): string {
  const installId = request.headers.get("x-install-id")?.trim() ?? "";
  if (!INSTALL_ID_PATTERN.test(installId)) {
    throw new HttpError(400, "invalid_install_id", "A valid X-Install-Id header is required.");
  }
  return installId;
}

export async function readJsonBody(request: Request, maxBytes: number): Promise<unknown> {
  const declared = request.headers.get("content-length");
  if (declared !== null && Number.parseInt(declared, 10) > maxBytes) {
    throw new HttpError(413, "payload_too_large", "The request is too large.");
  }
  const text = await request.text();
  if (text.length > maxBytes) {
    throw new HttpError(413, "payload_too_large", "The request is too large.");
  }
  if (text.trim().length === 0) {
    throw new HttpError(400, "invalid_json", "The request body is not valid JSON.");
  }
  try {
    return JSON.parse(text) as unknown;
  } catch {
    throw new HttpError(400, "invalid_json", "The request body is not valid JSON.");
  }
}

/**
 * Validate and normalise the chat request. Only `user` and `assistant` roles are
 * accepted: a client must never be able to inject a system message, because the
 * safety prompt is owned by the server.
 */
export function parseChatRequest(raw: unknown, config: Config): ChatRequest {
  if (!isRecord(raw)) {
    throw new HttpError(400, "invalid_body", "The request body must be a JSON object.");
  }

  const rawMessages = raw.messages;
  if (!Array.isArray(rawMessages) || rawMessages.length === 0) {
    throw new HttpError(400, "invalid_messages", "At least one message is required.");
  }
  if (rawMessages.length > config.maxMessages) {
    throw new HttpError(400, "too_many_messages", `A conversation can have at most ${config.maxMessages} messages.`);
  }

  const messages: ChatMessage[] = rawMessages.map((entry, index) => {
    if (!isRecord(entry)) {
      throw new HttpError(400, "invalid_message", `Message ${index + 1} is not an object.`);
    }
    const role = entry.role;
    if (role !== "user" && role !== "assistant") {
      throw new HttpError(400, "invalid_role", `Message ${index + 1} must come from the user or the assistant.`);
    }
    const content = entry.content;
    if (typeof content !== "string" || content.trim().length === 0) {
      throw new HttpError(400, "empty_message", `Message ${index + 1} is empty.`);
    }
    if (content.length > config.maxMessageChars) {
      throw new HttpError(
        400,
        "message_too_long",
        `Message ${index + 1} is longer than ${config.maxMessageChars} characters.`,
      );
    }
    return { role, content };
  });

  const rawShare = raw.shareMedications;
  if (rawShare !== undefined && typeof rawShare !== "boolean") {
    throw new HttpError(400, "invalid_share_flag", "shareMedications must be true or false.");
  }
  const shareMedications = rawShare === true;

  let medicationContext: string | undefined;
  const rawContext = raw.medicationContext;
  if (rawContext !== undefined && rawContext !== null) {
    if (typeof rawContext !== "string") {
      throw new HttpError(400, "invalid_medication_context", "medicationContext must be a string.");
    }
    if (!shareMedications) {
      throw new HttpError(
        400,
        "medication_context_not_allowed",
        "medicationContext is only accepted when shareMedications is true.",
      );
    }
    const trimmed = rawContext.trim();
    if (trimmed.length > config.maxMedicationContextChars) {
      throw new HttpError(
        400,
        "medication_context_too_long",
        `medicationContext is longer than ${config.maxMedicationContextChars} characters.`,
      );
    }
    medicationContext = trimmed.length > 0 ? trimmed : undefined;
  }

  return { messages, shareMedications, medicationContext };
}
